#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library. The rule is to
# leave it alone and author the per-step stages below the marker; it has been
# edited once, on purpose, to take out the .env write and the .env read-back that
# a wizard handling SVN credentials should not carry. See the note at the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later: it keeps nothing on this machine, so a re-run simply asks again.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# ask KEY "Prompt" reads a value into $KEY. Visible input (non-secret).
#
# An empty answer is refused and asked again. Every caller in this wizard hands
# what it gets straight to `gh secret set`, and an empty string there is stored
# and then reported as "✓ set" -- a failure that would not surface until the
# first tag, inside the deploy action. End of input is not an answer either, so
# a non-interactive run stops here instead of spinning.
ask() {
  local key="$1" prompt="$2" input=""
  while true; do
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    if ! read -r input; then
      printf '\n'
      warn "no more input to read, so $key was not set; re-run this from a terminal"
      exit 1
    fi
    [[ -n "$input" ]] && break
    warn "that was empty, and an empty value is worse here than no value"
  done
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" input=""
  while true; do
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    if ! read -rs input; then
      printf '\n'
      warn "no more input to read, so $key was not set; re-run this from a terminal"
      exit 1
    fi
    printf '\n'
    [[ -n "$input" ]] && break
    warn "that was empty, and an empty value is worse here than no value"
  done
  printf -v "$key" '%s' "$input"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the human half of .github/workflows/release.yml's wordpress.org deploy.
#
# The workflow's `wordpress-org` job reads two repository secrets, SVN_USERNAME and
# SVN_PASSWORD, and one repository variable, SVN_DRY_RUN. Only a repository admin can
# create them, which is why this is a wizard and not a step in the workflow.
#
# Nothing here is written to .env, and the library above can no longer do it: both write_env
# and the read-back of an existing .env value were removed rather than left unexercised.
# These credentials belong to a wordpress.org account and have no local use, so they live in
# GitHub's encrypted secret store and nowhere else on this machine, and a wizard that handles
# them has no dotfile code path at all.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "Alpaca Bot release: wordpress.org deploy credentials"

stage "The repository gh will write to"
say "gh writes secrets to whichever repository this directory belongs to."
say "Run this wizard from the alpaca-bot checkout, not from anywhere else."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo "unknown")
  say "gh reports this repository as: $REPO"
  if [[ "$REPO" != "carmelosantana/alpaca-bot" ]]; then
    warn "expected carmelosantana/alpaca-bot; stop and cd to that checkout if this is wrong"
  fi
else
  warn "gh is missing or not logged in. Every write below will be skipped and listed at the end."
fi
pause "Press Enter when this is the right repository."

stage "wordpress.org: the SVN repository exists"
say "The deploy commits to the plugin's own SVN repository. It has to exist already:"
say "the workflow publishes a version, it does not create a plugin listing."
open_url "https://plugins.svn.wordpress.org/alpaca-bot/"
step "You should see a directory listing with assets/, tags/ and trunk/."
step "If you get a 404, the plugin has not been approved yet. Stop here."
pause "Press Enter once you have seen assets/, tags/ and trunk/."

stage "SVN_USERNAME"
say "This is your wordpress.org login name, the one with commit rights to that repository."
say "It is the username, not the e-mail address, and not the display name."
open_url "https://profiles.wordpress.org/me/"
step "That link redirects to your own profile; the username is the last path segment."
ask WPORG_USERNAME "wordpress.org username:"
set_secret SVN_USERNAME "$WPORG_USERNAME"

stage "SVN_PASSWORD"
say "wordpress.org SVN accepts your account password. Entry below is hidden."
warn "The deploy action passes this to 'svn commit --password' on its command line."
warn "Treat it as a credential that a CI runner can see in its own process list."
open_url "https://login.wordpress.org/"
step "Only if you need to reset it first: use the lost-password link on that page."
ask_secret WPORG_PASSWORD "wordpress.org password:"
set_secret SVN_PASSWORD "$WPORG_PASSWORD"

stage "SVN_DRY_RUN"
say "This one is a repository VARIABLE, not a secret, and it is inverted on purpose."
say "release.yml passes dry-run as: vars.SVN_DRY_RUN != 'false'"
say "So any value that is not the word false -- including the variable not existing --"
say "means the deploy runs but commits nothing. GitHub ignores case when it compares"
say "strings, so false, False and FALSE all publish to wordpress.org for real."
say ""
say "Set it to true now. Flip it to false as part of the release decision, not before."
if confirm "Set SVN_DRY_RUN=true (recommended)?"; then
  set_var SVN_DRY_RUN "true"
else
  warn "Leaving SVN_DRY_RUN alone. The workflow still dry-runs unless it spells false."
fi
say ""
say "When the release is actually going out, run this by hand:"
note "  gh variable set SVN_DRY_RUN --body false"

finish
